    "        // Configure marked options if available",
    "        function setupMarkdownRenderer() {",
    "            if (typeof marked === \"undefined\") return;",
    "            const renderer = new marked.Renderer();",
    "            renderer.code = function(arg1, arg2, arg3) {",
    "                let code = '';",
    "                let lang = 'text';",
    "                if (typeof arg1 === 'object' && arg1 !== null) {",
    "                    code = arg1.text || arg1.raw || '';",
    "                    lang = arg1.lang || 'text';",
    "                } else {",
    "                    code = arg1 || '';",
    "                    lang = arg2 || 'text';",
    "                }",
    "                const escapedCode = escapeHtml(code);",
    "                const escapedLang = escapeHtml(lang || 'text');",
    "                return '<pre class=\"command-box code-snippet\" data-lang=\"' + escapedLang + '\">' +",
    "                       '<button class=\"code-copy-btn\" aria-label=\"复制代码\">' +",
    "                       '<svg viewBox=\"0 0 24 24\" width=\"12\" height=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" style=\"margin-right:2px\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>' +",
    "                       '<span>复制</span>' +",
    "                       '</button>' +",
    "                       '<code>' + escapedCode + '</code></pre>';",
    "            };",
    "            marked.use({ renderer });",
    "        }",
    "        document.addEventListener(\"DOMContentLoaded\",setupMarkdownRenderer);",
    "",
    "        // Markdown parser with fallback support",
    "        function parseMarkdown(text) {",
    "            if (typeof marked !== 'undefined' && typeof marked.parse === 'function') {",
    "                try {",
    "                    return marked.parse(String(text || \"\"));",
    "                } catch (e) {",
    "                    console.error(\"marked parse error:\", e);",
    "                }",
    "            }",
    "            const codeBlocks = [];",
    "            const source = String(text || \"\").replace(/^\\s+/, \"\").replace(/\\n{3,}/g, \"\\n\\n\");",
    "            let html = source.replace(/```(\\w*)\\n?([\\s\\S]*?)```/g, function(match, lang, code) {",
    "                const placeholder = \"%%CODE_BLOCK_\" + codeBlocks.length + \"%%\";",
    "                const cleanCode = code.replace(/^\\n+|\\n+$/g, \"\");",
    "                const label = lang || \"text\";",
    "                codeBlocks.push('<pre class=\"command-box code-snippet\" data-lang=\"' + escapeHtml(label) + '\"><button class=\"code-copy-btn\" aria-label=\"复制代码\"><svg viewBox=\"0 0 24 24\" width=\"12\" height=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" style=\"margin-right:2px\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg><span>复制</span></button><code>' + escapeHtml(cleanCode) + '</code></pre>');",
    "                return placeholder;",
    "            });",
    "            html = html.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\");",
    "            html = html.replace(/`([^`]+)`/g, \"<code style=\\\"background:rgba(255,140,66,0.1);padding:2px 6px;border-radius:4px;font-family:monospace;color:var(--accent);\\\">$1</code>\");",
    "            html = html.replace(/\\*\\*([^*]+)\\*\\*/g, \"<strong>$1</strong>\");",
    "            ",
    "            // Headings",
    "            html = html.replace(/^(#{1,6})\\s+(.+)$/gm, function(match, hashes, content) {",
    "                const level = hashes.length;",
    "                return \"<h\" + level + \">\" + content.trim() + \"</h\" + level + \">\";",
    "            });",
    "            ",
    "            // Lists",
    "            html = html.replace(/^\\s*[-*+]\\s+(.+)$/gm, \"<ul><li>$1</li></ul>\");",
    "            html = html.replace(/<\\/ul>\\s*<ul>/g, \"\");",
    "            html = html.replace(/^\\s*(\\d+)\\.\\s+(.+)$/gm, \"<ol><li value=\\\"$1\\\">$2</li></ol>\");",
    "            html = html.replace(/<\\/ol>\\s*<ol>/g, \"\");",
    "            ",
    "            html = html.replace(/\\n/g, \"<br>\");",
    "            ",
    "            // Clean up extra line breaks around lists and headings",
    "            html = html.replace(/<(h[1-6]|ul|ol|li|pre|code)([^>]*)><br>/g, \"<$1$2>\");",
    "            html = html.replace(/<br><\\/(h[1-6]|ul|ol|li|pre|code)>/g, \"</$1>\");",
    "            html = html.replace(/<\\/(h[1-6]|ul|ol|pre|code)><br>/g, \"</$1>\");",
    "            html = html.replace(/^(<br>)+/g, \"\");",
    "            html = html.replace(/(<br>\\s*){3,}/g, \"<br><br>\");",
    "            codeBlocks.forEach(function(block, index) {",
    "                html = html.replace(\"%%CODE_BLOCK_\" + index + \"%%\", block);",
    "            });",
    "            return html;",
    "        }",
