    "",
    "        /** 创建 Agent 回复骨架（avatar + bubble + 推理链容器） */",
    "        function createAgentSkeleton() {",
    "            const row = document.createElement(\"div\");",
    "            row.className = AGENT_MSG.ROW_CLS;row.setAttribute(\"aria-busy\",\"true\");",
    "            row.innerHTML =",
    "                '<div class=\"' + AGENT_MSG.AVATAR_CLS + '\">' + UI_ICONS.Assistant + '</div>' +",
    "                '<div class=\"' + AGENT_MSG.BUBBLE_CLS + '\"></div>';",
