    "            // 推理链容器（始终创建，可折叠）",
    "            const tw = document.createElement(\"details\");",
    "            tw.className = \"thinking-wrapper is-working\";tw.open=true;",
    "            tw.innerHTML =",
    "                '<summary class=\"thinking-header\"><span class=\"progress-icon\">' + UI_ICONS.LoaderCircle + '</span>' +",
    "                '<span class=\"progress-title\">正在阅读你的问题</span><span class=\"progress-elapsed\" aria-hidden=\"true\">0.0 秒</span>' + UI_ICONS.ChevronDown + '</summary>' +",
    "                '<section class=\"model-reasoning\" aria-label=\"模型思考\" hidden><h3>模型思考</h3><div class=\"reasoning-content\"></div></section>' +",
    "                '<div class=\"thinking-content\" style=\"display:none\"></div>' +",
    "                '<div class=\"thinking-body\"></div>';",
    "",
    "            const thinkingBody = tw.querySelector(\".thinking-body\");",
    "            const thinkingContentEl = tw.querySelector(\".thinking-content\");",
    "            tw.querySelector(\"summary\").addEventListener(\"click\",()=>{tw.dataset.userToggled=\"true\";});",
    "",
    "",
    "            // 最终回答文本区",
    "            const textContent = document.createElement(\"div\");",
    "            textContent.className = AGENT_MSG.TEXT_CONTENT_CLS;",
    "            textContent.hidden=true;",
    "            textContent.innerHTML = '<div class=\"typing-indicator\"><span></span><span></span><span></span></div>';",
    "            bubble.appendChild(tw);",
    "            bubble.appendChild(textContent);",
    "",
    "            const usageEl = document.createElement(\"div\");",
    "            usageEl.className = AGENT_MSG.USAGE_CLS;",
    "            usageEl.style.display = \"none\";",
    "            tw.appendChild(usageEl);",
    "            ",
    "            const skeleton={ row, bubble, thinkingWrapper: tw, thinkingBody, thinkingContent: thinkingContentEl, textContent, usageEl, startedAt:Date.now(), progressTitle:tw.querySelector(\".progress-title\"), progressElapsed:tw.querySelector(\".progress-elapsed\"), reasoningSection:tw.querySelector(\".model-reasoning\"), reasoningContent:tw.querySelector(\".reasoning-content\"), reasoningText:\"\", reasoningResponseId:null };",
    "            skeleton.progressTimer=setInterval(()=>updateProgressElapsed(skeleton),500);",
    "            return skeleton;",
    "        }",
    "        function updateProgressElapsed(skeleton){skeleton.progressElapsed.textContent=(((skeleton.finishedAt||Date.now())-skeleton.startedAt)/1000).toFixed(1)+\" 秒\";}",
    "        function finishProgress(skeleton,{stopped=false,failed=false,keepOpen=false}={}){",
    "            clearInterval(skeleton.progressTimer);updateProgressElapsed(skeleton);",
    "            const details=skeleton.thinkingWrapper;",
    "            details.classList.remove(\"is-working\");details.classList.add(stopped?\"is-stopped\":failed?\"is-failed\":\"is-complete\");",
    "            details.querySelector(\".progress-icon\").innerHTML=UI_ICONS[stopped?\"Square\":failed?\"X\":\"Check\"];",
    "            skeleton.progressTitle.textContent=(stopped?\"已停止\":failed?\"处理未完成\":\"处理完成\")+(toolStepCounter?\" · \"+toolStepCounter+\" 个步骤\":\"\");",
    "            if(agentToolPanel)agentToolPanel.textContent=skeleton.progressTitle.textContent+\" · \"+skeleton.progressElapsed.textContent;",
    "            details.querySelectorAll(\".tool-call-header.running\").forEach(header=>{header.className=\"tool-call-header interrupted\";header.innerHTML=UI_ICONS[stopped?\"Square\":\"X\"]+\"<span>\"+(stopped?\"已停止等待此步骤\":\"此步骤未完成\")+\"</span>\";});",
    "            if(!details.dataset.userToggled)details.open=keepOpen||failed||Boolean(skeleton.reasoningText);",
    "            skeleton.row.setAttribute(\"aria-busy\",\"false\");",
    "        }",
    "",
    "        function renderGlobalToolPanel() {",
    "            if (!agentToolPanel) return;",
