    "",
    "        function resetThinking() { thinkingText = \"\"; toolStepCounter = 0; }",
    "        function handleReasoningEvent(skeleton,event){",
    "            if(typeof event.content!==\"string\"||!event.content.length)return;",
    "            const content=skeleton.reasoningContent,position=content.scrollTop;",
    "            const follow=content.scrollHeight-position-content.clientHeight<32;",
    "            if(event.response_id&&skeleton.reasoningResponseId&&event.response_id!==skeleton.reasoningResponseId)skeleton.reasoningText+=\"\\n\\n\";",
    "            if(event.response_id)skeleton.reasoningResponseId=event.response_id;",
    "            skeleton.reasoningText+=event.content;content.textContent=skeleton.reasoningText;",
