    "            if(!skeleton.thinkingWrapper.dataset.userToggled)skeleton.thinkingWrapper.open=true;",
    "            setStatus(\"正在思考…\",skeleton);",
    "            content.scrollTop=follow?content.scrollHeight:position;scrollToLatest();",
    "        }",
    "",
    "        function formatEventClock() {",
    "            var now = new Date();",
    "            var hh = String(now.getHours()).padStart(2, \"0\");",
    "            var mm = String(now.getMinutes()).padStart(2, \"0\");",
    "            var ss = String(now.getSeconds()).padStart(2, \"0\");",
    "            return hh + \":\" + mm + \":\" + ss;",
    "        }",
    "",
    "        function formatToolArguments(rawArgs) {",
    "            if (rawArgs === null || rawArgs === undefined || rawArgs === \"\") return \"{}\";",
    "            if (typeof rawArgs === \"object\") return JSON.stringify(rawArgs, null, 2);",
    "            var text = String(rawArgs);",
    "            try {",
    "                return JSON.stringify(JSON.parse(text), null, 2);",
    "            } catch (e) {",
    "                return text;",
    "            }",
    "        }",
