    "        // ── Tool Call 卡片（✅ 工具执行成功 + 结果框） ─────────────────────",
    "        function handleToolCallEvent(skeleton, toolName, toolArgs) {",
    "            var body = skeleton.thinkingBody;",
    "            if (!body) return null;",
    "            markToolActive(toolName, \"running\");",
    "            toolStepCounter += 1;",
    "            var blockId = \"tool-\" + toolName.replace(/:/g, \"-\") + \"-\" + Date.now();",
    "            var block = document.createElement(\"div\");",
    "            block.className = \"tool-call-log\";",
    "            block.id = blockId;",
    "            block.dataset.toolName = toolName;",
    "            block.dataset.toolStep = String(toolStepCounter);",
    "            var formattedArgs = formatToolArguments(toolArgs);",
    "            var showArgs = toolName !== \"intent_classify\" && formattedArgs !== \"{}\";",
    "            block.innerHTML =",
    "                '<div class=\"tool-call-header running\">' +",
    "                '<svg class=\"spin-svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 2v4\"/></svg>' +",
    "                '<span>步骤 ' + toolStepCounter + ' · 正在调用工具: ' + escapeHtml(toolLabel(toolName)) + '...</span><span class=\"tool-time\">' + formatEventClock() + '</span></div>';",
    "            if (showArgs) {",
    "                block.innerHTML += '<details class=\"tool-call-args\"><summary>工具入参</summary><pre class=\"tool-call-output tool-call-args-code\">' + escapeHtml(formattedArgs) + '</pre></details>';",
    "            }",
    "            body.appendChild(block);",
    "            activeToolCards.set(blockId, { el: block, name: toolName, done: false });",
    "            scrollToLatest();",
    "            return blockId;",
    "        }",
    "",
    "        function handleToolResultEvent(skeleton, toolName, resultText, partial) {",
    "            var body = skeleton ? skeleton.thinkingBody : null;",
    "            if (!body) return;",
    "            markToolActive(toolName, partial ? \"running\" : \"success\");",
    "            var items = body.querySelectorAll(\".tool-call-log\");",
    "            var matchedBlock = null;",
    "            for (var i = items.length - 1; i >= 0; i--) {",
    "                var header = items[i].querySelector(\".tool-call-header\");",
    "                if (header && header.classList.contains(\"running\") && items[i].dataset.toolName === toolName) {",
    "                    matchedBlock = items[i]; break;",
    "                }",
    "            }",
    "            if (matchedBlock) {",
    "                var header = matchedBlock.querySelector(\".tool-call-header\");",
    "                var stepText = matchedBlock.dataset.toolStep ? (\"步骤 \" + matchedBlock.dataset.toolStep + \" · \") : \"\";",
    "                if (partial) {",
