    "",
    "        /** 为特殊工具渲染富内容（diagnose 表格 / analyze+fix 问题卡片）到已创建的工具卡片中 */",
    "        function renderRichToolContent(skeleton, toolName, content, partial) {",
    "            var body = skeleton ? skeleton.thinkingBody : null;",
