    "",
    "        // ── 特殊工具：诊断（镜像检测表格） ──────────────────────────────",
    "        function renderDiagnoseRichContent(container, data, partial) {",
    "            var report = data && Array.isArray(data.report) ? data.report : [];",
    "            if (!report.length) {",
    "                container.innerHTML = '<div class=\"tool-empty\">正在等待镜像响应...</div>';",
    "                return;",
    "            }",
    "            function timingLabel(label, value) { return typeof value === \"number\" ? label + value + \"ms\" : \"\"; }",
    "            var rows = report.map(function(r) {",
    "                var latency = typeof r.latency_ms === \"number\" && r.latency_ms < 9999 ? r.latency_ms + \" ms\" : \"-\";",
    "                var shortHash = r.commit_hash ? escapeHtml(String(r.commit_hash).slice(0, 10)) : \"-\";",
    "                var method = r.method === \"sandbox_deep\" ? \"\\u6c99\\u7bb1\\u6df1\\u6d4b\" : r.method === \"sandbox\" ? \"\\u6c99\\u7bb1\" : \"\\u8fb9\\u7f18\";",
    "                var note = r.network_note || (r.sync_status === \"network_restricted\" ? \"当前检测节点无法取得官方基准，不代表官方源故障\" : \"\");",
    "                var details = [note, r.error ? \"检测详情: \" + r.error : \"\", r.commit_ref ? \"分支 \" + r.commit_ref.replace(\"refs/heads/\", \"\") : \"\", method, timingLabel(\"DNS \", r.dns_ms), timingLabel(\"TCP \", r.tcp_ms), timingLabel(\"TLS \", r.tls_ms), timingLabel(\"Git \", r.git_ms), r.ip ? \"IP \" + r.ip : \"\"].filter(Boolean).join(\" · \");",
    "                return '<div class=\"tool-row\">' +",
    "                    '<span class=\"tool-main\" title=\"' + escapeHtml(details || r.name || \"\") + '\"><strong>' + escapeHtml(r.name || \"Unknown\") + '</strong><span>' + escapeHtml(details) + '</span></span>' +",
    "                    '<span class=\"tool-mono\">' + latency + '</span>' +",
    "                    statusBadge(r.sync_status, !!r.error && r.sync_status !== \"network_restricted\") +",
