    "            var parts = [];",
    "            if (data && data.doctor && data.doctor.assessment) {",
    "                var assessment = data.doctor.assessment;",
    "                parts.push('<div class=\"doctor-assessment\"><strong>先看对安装软件的影响</strong><dl class=\"impact-summary\"><dt>能安装软件吗？</dt><dd>' + escapeHtml(assessment.installation_impact || '目前信息不足，需要结合具体警告判断。') + '</dd><dt>现在需要处理吗？</dt><dd>' + escapeHtml(assessment.action_required || '先确认警告涉及的范围，再决定下一步。') + '</dd></dl></div>');",
    "            }",
    "            if (data && data.scope === \"provided_text\") parts.push('<p class=\"tool-empty\">仅分析已提供的报告，未检查或修改本机。</p>');",
    "            if (data && data.doctor && data.doctor.ready && !data.doctor.assessment) parts.push('<p>这份自检报告未记录警告，但未验证实际安装、网络或两端配置。</p>');",
    "            if (data && data.configuration) {",
