    "                    var status = {same:'已提供值一致',different:'存在差异',incomplete:'证据不足'}[row.status] || '证据不足';",
    "                    return '<tr><th scope=\"row\">' + escapeHtml(row.label || row.key) + '<br><code>' + escapeHtml(row.key) + '</code></th><td>' + value(row.terminal) + '</td><td>' + value(row.desktop) + '</td><td>' + escapeHtml((row.candidate_sources || []).join('、') || '尚未定位') + '</td><td>' + status + '</td></tr>';",
    "                }).join('');",
    "                parts.push('<details class=\"diagnostic-section\"><summary class=\"diagnostic-section-title\">查看下载地址和技术细节</summary><div class=\"config-comparison\"><table><thead><tr><th>设置</th><th>终端报告</th><th>桌面报告</th><th>候选配置来源</th><th>结论</th></tr></thead><tbody>' + configRows + '</tbody></table></div><p class=\"tool-empty\">文件值匹配仅表示候选来源，未确认最终覆盖关系；缺少字段不代表未配置。</p></details>');",
    "            }",
