    "                shareWrapper.style.padding = \"40px\";",
    "                shareWrapper.style.boxSizing = \"border-box\";",
    "                ",
    "                const exportStyle = document.createElement(\"style\");",
    "                exportStyle.textContent = isLight ? \".share-export-light,.share-export-light *{opacity:1!important;text-shadow:none!important}.share-export-light .message,.share-export-light .agent-text-content,.share-export-light .thinking-content,.share-export-light .tool-call-output,.share-export-light .tool-raw-output,.share-export-light .tool-command-box{color:#25272b!important}.share-export-light .message.system,.share-export-light .agent-text-content{background:#ffffff!important;border-color:#dce0e4!important}.share-export-light .message.system strong,.share-export-light .agent-text-content strong{color:#b94713!important}.share-export-light .message.user{background:#fff0e8!important;border-color:#dce0e4!important;color:#b94713!important}.share-export-light .agent-avatar{background:#fff0e8!important;border-color:#dce0e4!important;color:#b94713!important}.share-export-light .thinking-wrapper{background:#ffffff!important;border-color:#dce0e4!important}.share-export-light .thinking-header{background:#eff1f3!important;border-bottom-color:#dce0e4!important;color:#626771!important}.share-export-light .thinking-content{background:#f2f4f5!important;border-bottom-color:#dce0e4!important}.share-export-light .tool-call-log{background:#ffffff!important;border-color:#dce0e4!important}.share-export-light .tool-call-header.running{background:#fff0e8!important;color:#b94713!important}.share-export-light .tool-call-header.success{background:#edf8f0!important;color:#218653!important}.share-export-light .tool-time,.share-export-light .tool-call-args summary,.share-export-light .tool-main span,.share-export-light .tool-mono,.share-export-light .agent-usage{color:#626771!important}.share-export-light .tool-call-output,.share-export-light .tool-raw-output,.share-export-light .command-box{background:#f2f4f5!important;border-color:#dce0e4!important;color:#25272b!important}.share-export-light code{color:#b94713!important}.share-export-light .agent-usage{border-top-color:#dce0e4!important}.share-export-light .tool-rich-body{background:#f2f4f5!important;border-top-color:#dce0e4!important}.share-export-light .tool-grid-head{background:#eff1f3!important;color:#25272b!important}.share-export-light .tool-row{border-bottom-color:#dce0e4!important}.share-export-light .tool-main{color:#25272b!important}\" : \"\";",
    "                shareWrapper.appendChild(exportStyle);",
    "                ",
    "                const terminalCard = document.createElement(\"div\");",
    "                terminalCard.style.background = isLight ? \"#ffffff\" : \"#141517\";",
    "                terminalCard.style.border = isLight",
    "                    ? \"1px solid #dce0e4\"",
    "                    : \"1px solid #363a40\";",
    "                terminalCard.style.borderRadius = \"8px\";",
    "                terminalCard.style.boxShadow = isLight",
    "                    ? \"0 24px 60px #0000000a\"",
    "                    : \"0 24px 60px rgba(0,0,0,0.5)\";",
    "                terminalCard.style.overflow = \"hidden\";",
    "                terminalCard.style.display = \"flex\";",
    "                terminalCard.style.flexDirection = \"column\";",
    "                ",
    "                const header = document.createElement(\"div\");",
    "                header.className = \"terminal-header\";",
    "                header.style.background = isLight ? \"#eff1f3\" : \"#24272b\";",
    "                header.style.borderBottom = isLight",
    "                    ? \"1px solid #dce0e4\"",
    "                    : \"1px solid #363a40\";",
    "                header.style.padding = \"14px 24px\";",
    "                header.style.display = \"flex\";",
    "                header.style.alignItems = \"center\";",
    "                ",
    "                const headerTextColor = isLight ? \"#25272b\" : \"#f0f1f3\";",
    "                header.innerHTML = '<div class=\"terminal-dots\" style=\"display:flex;gap:6px\"><span class=\"dot red\" style=\"width:10px;height:10px;background:#ff5f56;border-radius:50%\"></span><span class=\"dot yellow\" style=\"width:10px;height:10px;background:#ffbd2e;border-radius:50%\"></span><span class=\"dot green\" style=\"width:10px;height:10px;background:#27c93f;border-radius:50%\"></span></div><div style=\"margin:0 auto;color:' + headerTextColor + ';font-size:0.85rem;font-family:var(--font-mono);font-weight:700\">brew-ai @ homebrew-cn</div>';",
    "                terminalCard.appendChild(header);",
    "                ",
    "                const messagesClone = messagesContainer.cloneNode(true);",
