    "                footer.innerHTML = '<div style=\"display:flex;align-items:center;gap:12px\"><span style=\"font-size:1.6rem\">🍺</span><div style=\"display:flex;flex-direction:column;gap:3px\"><span style=\"font-weight:700;font-size:0.85rem;color:' + titleColor + '\">Homebrew CN 智能助手</span><span style=\"font-size:0.72rem;color:' + subColor + '\">极速安装 · 镜像检测 · 环境诊断</span></div></div><div style=\"font-family:var(--font-mono);font-weight:700;font-size:0.85rem;color:var(--accent)\">brew-cn.mintimate.cn</div>';",
    "                terminalCard.appendChild(footer);",
